-- Competitions use their own scores and attempts, including previously completed courses.
insert into auth.users(id,email,email_confirmed_at) select ('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'competition'||n||'@example.test',now() from generate_series(40,44) n;
insert into public.profiles(user_id,full_name) select id,'Competitor '||right(id::text,2) from auth.users where email like 'competition%@example.test';
insert into public.organizations(id,name) values('10000000-0000-0000-0000-000000000040','Competition A'),('10000000-0000-0000-0000-000000000041','Competition B');
insert into public.organization_memberships(id,organization_id,user_id,email,role)
select ('20000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,case when n<43 then '10000000-0000-0000-0000-000000000040' else '10000000-0000-0000-0000-000000000041' end::uuid,('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'competition'||n||'@example.test',case when n in (40,43) then 'manager' else 'employee' end from generate_series(40,44) n;
set role authenticated;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
select public.release_training_course('10000000-0000-0000-0000-000000000040','c1000000-0000-4000-8000-000000000001');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000040';
select public.assign_training('c1000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000040',array['20000000-0000-0000-0000-000000000041'::uuid],deadline=>current_date+30);
insert into test.codes select 'comp-a1',id::text from public.training_assignments where membership_id='20000000-0000-0000-0000-000000000041';
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000041';
select test.complete_training((select code::uuid from test.codes where label='comp-a1'));
select public.submit_training_quiz((select code::uuid from test.codes where label='comp-a1'),test.training_answers(5),gen_random_uuid());
select test.rejects($q$select public.create_training_competition('10000000-0000-0000-0000-000000000040','c1000000-0000-4000-8000-000000000001','Unauthorized',current_date,current_date+1,'Lunch',all_employees=>true)$q$,'Manager access required','employee cannot create competitions');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000040';
select test.rejects($q$select public.create_training_competition('10000000-0000-0000-0000-000000000041','c1000000-0000-4000-8000-000000000001','Wrong store',current_date,current_date+1,'Lunch',all_employees=>true)$q$,'Manager access required','cross-store create blocked');
select test.rejects($q$select public.create_training_competition('10000000-0000-0000-0000-000000000040','c1000000-0000-4000-8000-000000000001','Wrong person',current_date,current_date+1,'Lunch',employee_ids=>array['20000000-0000-0000-0000-000000000044'::uuid])$q$,'Choose active employees','cross-store participant blocked');
select test.rejects($q$select public.create_training_competition('10000000-0000-0000-0000-000000000040','c1000000-0000-4000-8000-000000000001','Backdate',current_date-2,current_date+1,'Lunch',all_employees=>true)$q$,'Choose today','backdated competitions rejected');
insert into test.codes select 'comp-event',(public.create_training_competition('10000000-0000-0000-0000-000000000040','c1000000-0000-4000-8000-000000000001','Service challenge',(now() at time zone 'America/New_York')::date,current_date+2,'Pizza',all_employees=>true)->>'competition_id');
insert into test.codes select 'comp-a2',id::text from public.training_assignments where membership_id='20000000-0000-0000-0000-000000000042';
select test.ok((select count(*) from public.training_competition_participants where competition_id=(select code::uuid from test.codes where label='comp-event'))=2,'already-passed employee included with new employee');
select test.ok((select due_date=current_date+30 and completed_at is not null from public.training_assignments where id=(select code::uuid from test.codes where label='comp-a1')),'competition preserves existing deadline and course credit');
select test.ok((select due_date=current_date+2 from public.training_assignments where id=(select code::uuid from test.codes where label='comp-a2')),'new course assignment uses competition deadline');
select test.rejects($q$select public.create_training_competition('10000000-0000-0000-0000-000000000040','c1000000-0000-4000-8000-000000000001','Overlap',current_date,current_date+1,'Lunch',all_employees=>true)$q$,'overlap another competition','overlapping schedules blocked');
select test.rejects('select * from private.training_challenge_attempts','permission denied','manager cannot inspect individual challenge answers');
select test.rejects($q$update public.training_competition_participants set attempt_limit=99$q$,'permission denied','direct challenge limit manipulation denied');
select test.rejects($q$select private.training_workspace_core('10000000-0000-0000-0000-000000000040')$q$,'permission denied','old workspace core is private');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000044';
select test.ok((select count(*) from public.training_competitions)=0,'other store cannot see competition rows');
select test.rejects($q$select public.get_training_competitions('10000000-0000-0000-0000-000000000040')$q$,'Active store access required','other store cannot read competition report');
select test.rejects($q$select public.submit_training_challenge((select code::uuid from test.codes where label='comp-event'),test.training_answers(5),gen_random_uuid())$q$,'Active competition participation required','nonparticipant cannot submit challenge');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000042';
select test.rejects($q$select public.submit_training_challenge((select code::uuid from test.codes where label='comp-event'),test.training_answers(5),gen_random_uuid())$q$,'Pass the required course','new learner must pass course before challenge');
select test.rejects($q$select public.record_training_activity((select code::uuid from test.codes where label='comp-a1'))$q$,'Active course assignment required','cannot log time against another person assignment');
select test.ok(public.record_training_activity((select code::uuid from test.codes where label='comp-a2'))=0,'first heartbeat establishes baseline');
reset role;
update public.training_competitions set created_at=clock_timestamp()-interval '2 minutes' where id=(select code::uuid from test.codes where label='comp-event');
update private.training_activity_sessions set last_seen=clock_timestamp()-interval '30 seconds' where user_id='00000000-0000-0000-0000-000000000042';
set role authenticated;
select test.ok(public.record_training_activity((select code::uuid from test.codes where label='comp-a2'))=20,'delayed heartbeat bounded to twenty seconds');
select test.ok(public.record_training_activity((select code::uuid from test.codes where label='comp-a2'))=0,'duplicate heartbeat cannot add more time');
reset role;
update private.training_activity_sessions set last_seen=clock_timestamp()-interval '2 minutes' where user_id='00000000-0000-0000-0000-000000000042';
set role authenticated;
select test.ok(public.record_training_activity((select code::uuid from test.codes where label='comp-a2'),false)=0,'idle gap adds no time');
select test.ok(public.get_training_competitions('10000000-0000-0000-0000-000000000040')->0->'learning_seconds'='null','employee does not see coworker time');
select test.rejects('select * from private.training_learning_intervals','permission denied','raw learning intervals remain private');
select test.complete_training((select code::uuid from test.codes where label='comp-a2'));
select public.submit_training_quiz((select code::uuid from test.codes where label='comp-a2'),test.training_answers(5),gen_random_uuid());
select test.ok(public.get_training_competitions('10000000-0000-0000-0000-000000000040')->0->>'top_score'='0','course quiz does not create competition score');
select test.rejects($q$select public.submit_training_challenge((select code::uuid from test.codes where label='comp-event'),'[]',gen_random_uuid())$q$,'Answer every challenge question','malformed challenge does not consume attempt');
insert into test.codes select 'comp-key',gen_random_uuid()::text;
select test.ok(public.submit_training_challenge((select code::uuid from test.codes where label='comp-event'),test.training_answers(4),(select code::uuid from test.codes where label='comp-key'))->>'points'='40','challenge awards its own correct-answer score');
select test.ok(public.submit_training_challenge((select code::uuid from test.codes where label='comp-event'),test.training_answers(5),(select code::uuid from test.codes where label='comp-key'))->>'points'='40','challenge duplicate returns original result');
select public.submit_training_challenge((select code::uuid from test.codes where label='comp-event'),test.training_answers(2),gen_random_uuid());
select public.submit_training_challenge((select code::uuid from test.codes where label='comp-event'),test.training_answers(0),gen_random_uuid());
select test.ok(public.get_training_competitions('10000000-0000-0000-0000-000000000040')->0->>'top_score'='40','lower retry does not reduce best score');
select test.rejects($q$select public.submit_training_challenge((select code::uuid from test.codes where label='comp-event'),test.training_answers(5),gen_random_uuid())$q$,'Ask your manager','fourth challenge attempt blocked');
select test.rejects($q$select public.unlock_training_challenge((select code::uuid from test.codes where label='comp-event'),'20000000-0000-0000-0000-000000000042','Help myself')$q$,'Manager access required','learner cannot unlock their challenge');
select test.ok(public.get_training_workspace('10000000-0000-0000-0000-000000000040')->'totals'->>'lifetime_points'='50','challenge never duplicates lifetime points');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000040';
select test.ok(public.unlock_training_challenge((select code::uuid from test.codes where label='comp-event'),'20000000-0000-0000-0000-000000000042','Reviewed the explanations together')=4,'manager grants one supported challenge retry');
select test.ok((public.get_training_competitions('10000000-0000-0000-0000-000000000040')->0->>'learning_seconds')::integer=20,'manager report contains measured learning time');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000042';
select test.ok(public.submit_training_challenge((select code::uuid from test.codes where label='comp-event'),test.training_answers(5),gen_random_uuid())->>'attempts_used'='4','supported challenge attempt works');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000041';
select public.submit_training_challenge((select code::uuid from test.codes where label='comp-event'),test.training_answers(5),gen_random_uuid());
select test.ok(public.get_training_competitions('10000000-0000-0000-0000-000000000040')->0->>'team_goal_met'='true','team goal includes passing review challenge for prior graduate');
select test.ok((select bool_and(p->>'rank'='1') from jsonb_array_elements(public.get_training_competitions('10000000-0000-0000-0000-000000000040')->0->'standings')p),'equal best scores share first rank');
select test.ok(public.get_training_workspace('10000000-0000-0000-0000-000000000040')->'totals'->>'trophies'='1','review challenge does not duplicate trophy');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000040';
select public.finish_training_competition((select code::uuid from test.codes where label='comp-event'));
select test.ok(public.get_training_competitions('10000000-0000-0000-0000-000000000040')->0->>'status'='ended','ending competition preserves readable history');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000041';
select test.rejects($q$select public.submit_training_challenge((select code::uuid from test.codes where label='comp-event'),test.training_answers(5),gen_random_uuid())$q$,'not running','new submissions blocked after closing');
reset role;
-- Removing an employee after an event ends must not rewrite its historical outcome.
update public.organization_memberships set status='inactive',deactivated_at=clock_timestamp() where id='20000000-0000-0000-0000-000000000041';
set role authenticated;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000040';
select test.ok(public.get_training_competitions('10000000-0000-0000-0000-000000000040')->0->>'participants'='2','later removal preserves past competition cohort');
insert into test.codes select 'comp-future',(public.create_training_competition('10000000-0000-0000-0000-000000000040','c1000000-0000-4000-8000-000000000001','Spring review',make_date(extract(year from current_date)::integer+1,3,1),make_date(extract(year from current_date)::integer+1,3,31),'Lunch',all_employees=>true)->>'competition_id');
select test.ok((select extract(epoch from ends_at-starts_at)=31*86400-3600 from public.training_competitions where id=(select code::uuid from test.codes where label='comp-future')),'store-local whole-day schedule handles daylight-saving change');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000042';
select test.rejects($q$select public.submit_training_challenge((select code::uuid from test.codes where label='comp-future'),test.training_answers(5),gen_random_uuid())$q$,'not running','challenge cannot be taken before scheduled start');
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000040';
select public.finish_training_competition((select code::uuid from test.codes where label='comp-future'));
select test.ok(public.get_training_competitions('10000000-0000-0000-0000-000000000040')->0->>'status'='canceled','future competition can be canceled without deleting history');
reset role;
select test.ok(not has_function_privilege('anon','public.submit_training_challenge(uuid,jsonb,uuid)','execute'),'anonymous challenge submit denied');
-- A canceled event never admits submissions, and current departures cannot keep playing.
set role authenticated;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000042';
select test.rejects($q$select public.submit_training_challenge((select code::uuid from test.codes where label='comp-future'),test.training_answers(5),gen_random_uuid())$q$,'not running','canceled competition rejects challenges');
reset role;
update public.organization_memberships set status='inactive',deactivated_at=clock_timestamp() where id='20000000-0000-0000-0000-000000000042';
set role authenticated;
select test.rejects($q$select public.get_training_competitions('10000000-0000-0000-0000-000000000040')$q$,'Active store access required','removed employee loses competition report access');
select test.rejects($q$select public.submit_training_challenge((select code::uuid from test.codes where label='comp-event'),test.training_answers(5),(select code::uuid from test.codes where label='comp-key'))$q$,'Active competition participation required','removed employee cannot replay answers to regain private review');
select test.rejects($q$select public.record_training_activity((select code::uuid from test.codes where label='comp-a2'))$q$,'Active course assignment required','removed employee cannot add learning time');
reset role;
-- Restore this controlled membership solely for the runner's separate concurrency scenario.
update public.organization_memberships set status='active',deactivated_at=null where id='20000000-0000-0000-0000-000000000042';
select 'Passed competition, review challenge, and learning time checks ('||count(*)||' total SQL assertions).' from test.results;
